using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Diagnostics;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Web.Script.Serialization;
using Forms=System.Windows.Forms;
class DesktopMovementUiTests {
 static int checks,failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static void Set(object o,string n,object value){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(o,value);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}
 static void Check(bool ok,string text){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+text);}
 static void Pump(int ms=30){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static T Find<T>(DependencyObject o,Func<T,bool> test)where T:DependencyObject{var item=o as T;if(item!=null&&test(item))return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var match=Find<T>(VisualTreeHelper.GetChild(o,i),test);if(match!=null)return match;}return null;}
 static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var bitmap=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(path))encoder.Save(output);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;string from="",to="";double largestStep=0;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump(400);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);Pump(100);Set(pet,"assistantSnapshot",new AssistantSnapshot{CodexRow=-1,Watches=new WatchedProcess[0],Notices=new string[0]});((BubbleQueue)Get(pet,"messages")).Clear();Set(pet,"roam",true);Set(pet,"awakeUntil",Double.MaxValue);Set(pet,"nextIdleGesture",Double.MaxValue);Set(pet,"actionUntil",0.0);Set(pet,"signatureUntil",0.0);Set(pet,"nextWalk",Double.MaxValue);var clock=(Stopwatch)Get(pet,"clock");
 Check((bool)Get(pet,"crossScreens"),"cross-screen movement enabled by default");var source=PresentationSource.FromVisual(pet);var transform=source.CompositionTarget.TransformFromDevice;var displays=Forms.Screen.AllScreens.Select(s=>new{Screen=s,Work=new Rect(transform.Transform(new Point(s.WorkingArea.Left,s.WorkingArea.Top)),transform.Transform(new Point(s.WorkingArea.Right,s.WorkingArea.Bottom)))}).OrderBy(s=>s.Work.Left).ToArray();Check(displays.Length>=2,"two physical Windows displays available for native check");var left=displays[0];var right=displays[1];double y=Math.Max(left.Work.Top,right.Work.Top)+(Math.Min(left.Work.Bottom,right.Work.Bottom)-Math.Max(left.Work.Top,right.Work.Top)-pet.Height)/2;pet.Left=right.Work.Left+20;pet.Top=y;Call(pet,"ClampWindow");Call(pet,"BeginDesktopTravel");Set(pet,"moveMode","roam");Set(pet,"moveX",pet.Left);Set(pet,"moveY",pet.Top);Set(pet,"targetX",left.Work.Right-pet.Width-80);Set(pet,"targetY",y);Set(pet,"walkUntil",clock.Elapsed.TotalSeconds+60);from=Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(pet).Handle).DeviceName;
 int frames=0;for(;frames<600&&(double)Get(pet,"walkUntil")>clock.Elapsed.TotalSeconds;frames++){var before=new Point(pet.Left,pet.Top);Set(pet,"lastTick",clock.Elapsed.TotalSeconds-.02);Call(pet,"Tick",null,EventArgs.Empty);largestStep=Math.Max(largestStep,(new Point(pet.Left,pet.Top)-before).Length);Pump(1);}to=Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(pet).Handle).DeviceName;Check(from!=to&&pet.Left<right.Work.Left,"real pet HWND crosses from primary to left display via Tick");Check(largestStep<8&&frames>50,"walking crosses continuously with ordinary frame-size steps");Check((double)Get(pet,"motionDistance")>pet.Width,"walking animation distance accumulates across seam");
 // Reverse the same runtime path using the skateboard speed and sprite branch.
 Set(pet,"moveMode","skate");Set(pet,"desktopMovement",null);Set(pet,"moveX",pet.Left);Set(pet,"moveY",pet.Top);Set(pet,"targetX",right.Work.Left+100);Set(pet,"targetY",y);Set(pet,"walkUntil",clock.Elapsed.TotalSeconds+60);Set(pet,"nextWalk",Double.MaxValue);for(int i=0;i<600&&(double)Get(pet,"walkUntil")>clock.Elapsed.TotalSeconds;i++){Set(pet,"lastTick",clock.Elapsed.TotalSeconds-.02);Call(pet,"Tick",null,EventArgs.Empty);Pump(1);}Check(Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(pet).Handle).DeviceName==from,"skateboard runtime returns across displays");

 var pointer=(Point)Call(pet,"CursorPoint");var pointerScreen=displays.OrderBy(d=>Math.Abs((d.Work.Left+d.Work.Width/2)-pointer.X)).First();var opposite=displays.First(d=>d.Screen.DeviceName!=pointerScreen.Screen.DeviceName);pet.Left=opposite.Work.Left+opposite.Work.Width/2-pet.Width/2;pet.Top=y;Call(pet,"ClampWindow");Set(pet,"moveMode","follow");Set(pet,"desktopMovement",null);Set(pet,"moveX",pet.Left);Set(pet,"moveY",pet.Top);Set(pet,"walkUntil",clock.Elapsed.TotalSeconds+60);Set(pet,"nextWalk",Double.MaxValue);for(int i=0;i<1500&&(double)Get(pet,"walkUntil")>clock.Elapsed.TotalSeconds;i++){Set(pet,"lastTick",clock.Elapsed.TotalSeconds-.02);Call(pet,"Tick",null,EventArgs.Empty);Pump(1);}Check(Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(pet).Handle).DeviceName==pointerScreen.Screen.DeviceName,"follow runtime crosses toward actual Windows cursor screen");

 var startingDisplay=displays.First(d=>d.Work.Contains(new Point(pet.Left+pet.Width/2,pet.Top+pet.Height/2)));Call(pet,"BeginSkateDemo",2.4);var demoGoal=new Point((double)Get(pet,"targetX")+pet.Width/2,(double)Get(pet,"targetY")+pet.Height/2);Check(!startingDisplay.Work.Contains(demoGoal),"manual skateboard action also selects another display");
 // Normal selection paths must include destinations on both screens.
 var targets=new List<double>();Set(pet,"moveMode","roam");for(int i=0;i<40;i++){Call(pet,"BeginDesktopTravel");targets.Add((double)Get(pet,"targetX"));}Check(targets.Any(x=>x<right.Work.Left)&&targets.Any(x=>x>=right.Work.Left),"random roaming chooses targets on both physical displays");Set(pet,"moveMode","patrol");targets.Clear();for(int i=0;i<8;i++){Call(pet,"BeginDesktopTravel");targets.Add((double)Get(pet,"targetX"));}Check(targets.Any(x=>x<right.Work.Left)&&targets.Any(x=>x>=right.Work.Left),"patrol corners include both displays");
 Call(pet,"PetSetting","crossScreens");Check(!(bool)Get(pet,"crossScreens"),"manual switch can restore current-screen-only movement");var current=(DesktopMovement)Call(pet,"MovementSpace");Check(current.Destinations(new Point(pet.Left,pet.Top)).Length==1,"disabled cross-screen switch restricts destination selection");Call(pet,"PetSetting","crossScreens");Set(pet,"crossScreens",false);Call(pet,"ReadPreferences");Check((bool)Get(pet,"crossScreens"),"cross-screen preference reloads from isolated settings");Call(pet,"OpenTerminal");var window=(TerminalWindow)Get(pet,"terminal");window.ShowPage("动作与移动");Pump();var toggle=Find<CheckBox>(window,c=>Convert.ToString(c.Content)=="跨显示器漫游");Check(toggle!=null&&toggle.IsChecked==true,"movement page exposes current cross-screen state");Shot(window,Path.Combine(args[0],"cross-screen-settings-native.png"));
 }catch(Exception e){failures++;Console.WriteLine(e);}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"movement-ui-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,physicalDisplays=Forms.Screen.AllScreens.Length,from,to,largestStep,real_pet_settings_changed=false,physical_mouse_follow_verified=false}));return failures==0?0:1;}
}
